import assert from "node:assert/strict";
import { resolveAdminTarget, assertDisposableName, disposableTarget } from "@/db/__tests__/helpers";
import { runOutboundWorker } from "../worker";

// TEST ONLY: isolated database and fake transport. Refuse any target not generated by the guarded harness.
const admin = resolveAdminTarget();
const supplied = process.env.WORKER_TEST_DATABASE_URL!;
const name = new URL(supplied).pathname.slice(1);
assertDisposableName(name);
assert.equal(supplied, disposableTarget(admin, name).url);
globalThis.fetch = async () => {
  throw new Error("no network transport in this fixture");
};
const controller = new AbortController();
const report = (event: string, detail: object = {}) =>
  process.stdout.write(
    JSON.stringify({ event, pid: process.pid, ppid: process.ppid, ...detail }) + "\n",
  );
let release: (() => void) | undefined;
process.on("message", (message) => {
  if (message === "release-send") release?.();
});
for (const signal of ["SIGTERM", "SIGINT"] as const)
  process.on(signal, () => {
    report("signal-ack", { signal });
    controller.abort();
  });
let calls = 0;
runOutboundWorker({
  env: {
    DATABASE_URL: supplied,
    WHATSAPP_OUTBOUND_ENABLED: "true",
    WHATSAPP_OUTBOUND_CONCURRENCY: "2",
  },
  signal: controller.signal,
  injectedTransport: true,
  now: () => new Date(Date.now() + Number(process.env.CHILD_CLOCK_OFFSET_MS ?? "0")),
  transport: {
    send: async (_request, _signal, hooks) => {
      const call = ++calls;
      hooks?.httpStarted();
      if (process.env.CHILD_SEND !== "accept") {
        const held = new Promise<void>((resolve) => {
          release = resolve;
        });
        report("fake-send-start", { call });
        await held;
      } else report("fake-send-start", { call });
      return {
        kind: "accepted",
        wamid: `wamid.LOCAL-${process.pid}-${call}`,
        providerStatus: null,
        httpStatus: 200,
      };
    },
  },
  sleep: async (_ms, signal) => {
    report("poll-idle", { calls });
    if (!signal.aborted)
      await new Promise<void>((resolve) =>
        signal.addEventListener("abort", () => resolve(), { once: true }),
      );
  },
})
  .then((code) => {
    report("exit", { code, calls });
    process.stdout.write("", () => process.exit(code));
  })
  .catch(() => {
    report("shutdown-error");
    process.exit(1);
  });
